+    <div class="brand">
+      <h1>Stillwater Yoga</h1>
+      <p>Book a mat for this week’s classes.</p>
+    </div>
+    <div class="facts">
+      <span><b>14 mats</b> per class</span>
+      <span>Arrive <b>10 min</b> early</span>
+      <span>Cancel up to <b>2 h</b> before</span>
+    </div>
+  </header>
+
+  <div id="status" class="notice" role="status">Loading bookings…</div>
+
+  <nav class="days" id="days" aria-label="Choose a day"></nav>
+
+  <div class="main">
+    <section aria-labelledby="dayTitle">
+      <div class="dayhead"><h2 id="dayTitle"></h2><span id="dayCount"></span></div>
+      <div class="classes" id="classes"></div>
+    </section>
+    <aside aria-labelledby="mineTitle">
+      <h2 id="mineTitle">Your mats</h2>
+      <ul class="mine" id="mine"></ul>
+      <p class="policy">Mats, blocks and straps are provided. Bring water and a towel for Warm Flow. If a class is full, check back: spots open when people cancel.</p>
+    </aside>
+  </div>
+</div>
+
+<script>
+(() => {
+  const CAP = 14, CANCEL_H = 2;
+  // Weekly timetable. dow: 0 = Sunday.
+  const TIMETABLE = [
+    {id:"sunrise", days:[1,3,5], t:"07:00", dur:60, name:"Sunrise Vinyasa", teacher:"Maya", level:"All levels", desc:"Steady breath-led flow to wake the body. Sun salutations, standing balances, short savasana."},
+    {id:"lunch", days:[2,4], t:"12:15", dur:45, name:"Lunchtime Flow", teacher:"Theo", level:"All levels", desc:"A compact class that fits a lunch break. Back in your chair by 13:15."},
+    {id:"hatha", days:[1,4], t:"18:00", dur:75, name:"Slow Hatha", teacher:"Rosa", level:"Beginner", desc:"Longer holds with clear alignment cues. A good first class."},
+    {id:"warm", days:[2,5], t:"18:30", dur:60, name:"Warm Flow", teacher:"Maya", level:"Intermediate", desc:"Room heated to 32 °C. Strong standing sequence, arm balances offered."},
+    {id:"yin", days:[3,0], t:"19:30", dur:75, name:"Yin & Breath", teacher:"Ana", level:"All levels", desc:"Floor-based poses held 3–5 minutes, then pranayama. Bolsters provided."},
+    {id:"weekend", days:[6], t:"09:30", dur:90, name:"Saturday Long Practice", teacher:"Theo", level:"Intermediate", desc:"Full practice with inversions and a guided 15-minute savasana."},
+    {id:"restore", days:[6,0], t:"16:00", dur:60, name:"Restorative", teacher:"Rosa", level:"Beginner", desc:"Supported, passive poses. Almost no effort, lots of props."}
+  ];
+
+  const $ = id => document.getElementById(id);
+  const pad = n => String(n).padStart(2,"0");
+  const ymd = d => `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
+  const fmtDay = new Intl.DateTimeFormat(undefined,{weekday:"long", month:"long", day:"numeric"});
+  const fmtShort = new Intl.DateTimeFormat(undefined,{weekday:"short", day:"numeric", month:"short"});
+  const fmtDow = new Intl.DateTimeFormat(undefined,{weekday:"short"});
+
+  const today = new Date(); today.setHours(0,0,0,0);
+  const week = Array.from({length:7},(_,i)=>{const d=new Date(today); d.setDate(d.getDate()+i); return d;});
+
+  function sessionsFor(d){
+    return TIMETABLE.filter(c=>c.days.includes(d.getDay())).map(c=>{
+      const [h,m]=c.t.split(":").map(Number);
+      const start=new Date(d); start.setHours(h,m,0,0);
+      const end=new Date(start.getTime()+c.dur*60000);
+      return {...c, key:`${ymd(d)}_${c.id}`, start, end};
+    }).sort((a,b)=>a.start-b.start);
+  }
+  const allSessions = new Map(week.flatMap(sessionsFor).map(s=>[s.key,s]));
+
+  const state = {
+    day: 0, db:null, user:null, me:null, isOwner:false, canWrite:true,
+    docs:{},          // uid -> array of session keys
+    loaded:false, busy:false, names:{}
+  };
+  try { const saved = Number(sessionStorage.getItem("stillwater-day")); if (saved>=0 && saved<7) state.day = saved; } catch(e){}
+
+  const mySessions = () => (state.me && state.docs[state.me]) || [];
+  function attendees(key){ return Object.entries(state.docs).filter(([,s])=>s.includes(key)).map(([u])=>u); }
+
+  function setStatus(msg, tone){
+    const el=$("status");
+    if(!msg){ el.hidden=true; return; }
+    el.hidden=false; el.textContent=msg; el.dataset.tone=tone||"";
+  }
+
+  function renderDays(){
+    const mine = new Set(mySessions().map(k=>k.slice(0,10)));
+    $("days").replaceChildren(...week.map((d,i)=>{
+      const b=document.createElement("button");
+      b.className="day"+(mine.has(ymd(d))?" has-mine":"");
+      b.id="day-"+i; b.type="button";
+      b.setAttribute("aria-pressed", String(i===state.day));
+      b.setAttribute("aria-label", fmtDay.format(d));
+      b.innerHTML=`<small>${i===0?"Today":fmtDow.format(d)}</small><span>${d.getDate()}</span><i></i>`;
+      b.onclick=()=>{state.day=i; try{sessionStorage.setItem("stillwater-day",String(i))}catch(e){} render();};
+      return b;
+    }));
+  }
+
+  function renderClasses(){
+    const d=week[state.day], list=sessionsFor(d), mine=new Set(mySessions()), now=new Date();
+    $("dayTitle").textContent = state.day===0 ? `Today, ${fmtDay.format(d)}` : fmtDay.format(d);
+    $("dayCount").textContent = `${list.length} ${list.length===1?"class":"classes"}`;
+    $("classes").replaceChildren(...list.map(s=>{
+      const who=attendees(s.key), taken=who.length, left=Math.max(0,CAP-taken), isMine=mine.has(s.key);
+      const started = now >= s.start;
+      const cutoff = now >= new Date(s.start.getTime()-CANCEL_H*3600000);
+      const row=document.createElement("article"); row.className="cls";
+      row.innerHTML=`
+        <div class="time">${s.t}<small>${s.dur} min</small></div>
+        <div class="info">
+          <h3></h3>
+          <div class="meta"></div>
+          <p class="desc"></p>
+          <div class="mats" aria-label="${taken} of ${CAP} mats booked">${Array.from({length:CAP},(_,i)=>`<b class="${i<taken?"on":""}"></b>`).join("")}<em class="${left<=3&&left>0?"low":""}"></em></div>
+        </div>
+        <div class="act"></div>`;
+      const h3=row.querySelector("h3"); h3.textContent=s.name;
+      const lvl=document.createElement("span"); lvl.className="lvl"; lvl.textContent=s.level; h3.append(lvl);
+      row.querySelector(".meta").textContent=`with ${s.teacher} · ends ${pad(s.end.getHours())}:${pad(s.end.getMinutes())}`;
+      row.querySelector(".desc").textContent=s.desc;
+      row.querySelector("em").textContent = !state.loaded ? "" : left===0 ? "Full" : `${left} mat${left===1?"":"s"} left`;
+
+      const act=row.querySelector(".act"), btn=document.createElement("button");
+      btn.type="button"; btn.id="btn-"+s.key; btn.className="btn";
+      if(started){ btn.textContent="Started"; btn.disabled=true; btn.classList.add("ghost"); }
+      else if(isMine){
+        const tag=document.createElement("span"); tag.className="booked"; tag.textContent="You’re booked"; act.append(tag);
+        btn.classList.add("ghost"); btn.textContent="Cancel";
+        if(cutoff){ btn.disabled=true; btn.title=`Cancellations close ${CANCEL_H} h before class`; }
+        btn.onclick=()=>toggle(s,false);
+      } else {
+        btn.textContent = left===0 ? "Full" : "Book mat";
+        btn.disabled = left===0;
+        btn.onclick=()=>toggle(s,true);
+      }
+      if(!state.db || !state.me || !state.canWrite || state.busy || !state.loaded) btn.disabled=true;
+      act.prepend(btn);
+
+      if(state.isOwner && who.length){
+        const det=document.createElement("details"); det.className="roster";
+        const sum=document.createElement("summary"); sum.textContent=`Roster (${who.length})`;
+        const ul=document.createElement("ul");
+        who.forEach(u=>{const li=document.createElement("li"); li.textContent=state.names[u]||"Someone"; ul.append(li);});
+        det.append(sum,ul); row.append(det);
+      }
+      return row;
+    }));
+  }
+
+  function renderMine(){
+    const items=mySessions().map(k=>allSessions.get(k)).filter(Boolean).filter(s=>s.end>new Date()).sort((a,b)=>a.start-b.start);
+    const ul=$("mine");
+    if(!items.length){
+      const li=document.createElement("li");
+      li.innerHTML=`<p class="empty"></p>`;
+      li.firstChild.textContent = state.me ? "No mats booked yet. Pick a class and tap Book mat." : "Sign in to claude.ai to book a mat.";
+      ul.replaceChildren(li); return;
+    }
+    ul.replaceChildren(...items.map(s=>{
+      const li=document.createElement("li");
+      const txt=document.createElement("div");
+      const st=document.createElement("strong"); st.textContent=s.name;
+      const sp=document.createElement("span"); sp.textContent=`${fmtShort.format(s.start)} · ${s.t}`;
+      txt.append(st,sp);
+      const b=document.createElement("button"); b.type="button"; b.className="linkbtn"; b.id="mine-"+s.key; b.textContent="Cancel";
+      const cutoff = new Date() >= new Date(s.start.getTime()-CANCEL_H*3600000);
+      b.disabled = cutoff || state.busy;
+      if(cutoff) b.title=`Cancellations close ${CANCEL_H} h before class`;
+      b.onclick=()=>toggle(s,false);
+      li.append(txt,b); return li;
+    }));
+  }
+
+  async function render(){
+    if(state.isOwner && state.user){
+      const ids=Object.keys(state.docs);
+      if(ids.length){ const ps=await state.user.profiles(ids); for(const id of ids) state.names[id]=ps[id]?.name||""; }
+    }
+    renderDays(); renderClasses(); renderMine();
+  }
+
+  async function toggle(s, book){
+    if(state.busy || !state.db || !state.me) return;
+    const current=mySessions();
+    if(book && attendees(s.key).length>=CAP){ setStatus(`${s.name} just filled up. Try another class.`); return; }
+    const keepFrom = ymd(new Date(today.getTime()-86400000));
+    let next = current.filter(k=>k!==s.key && k.slice(0,10)>=keepFrom);
+    if(book) next.push(s.key);
+    state.busy=true; render();
+    try{
+      await state.db.collection("bookings").doc(state.me).set({sessions:next, updated:new Date().toISOString()});
+      state.docs[state.me]=next;
+      setStatus(book ? `Booked: ${s.name}, ${fmtShort.format(s.start)} at ${s.t}. See you on the mat.` : `Cancelled ${s.name} on ${fmtShort.format(s.start)}. Your mat is free for someone else.`, "ok");
+    }catch(e){
+      if(e && e.code==="invalid_argument"){ state.canWrite=false; setStatus("Your access to this page is view-only, so you can see the timetable but not book. Ask the studio for Contributor access."); }
+      else if(e && e.code==="quota_exceeded") setStatus("The booking list is full. Ask the studio to clear out old bookings.");
+      else setStatus("That booking didn’t go through because the connection dropped. Try again in a moment.");
+    }finally{ state.busy=false; render(); }
+  }
+
+  render();
+
+  (async()=>{
+    const [db,user] = await Promise.all([claude.use("db"), claude.use("user")]);
+    state.db=db; state.user=user;
+    if(!db){
+      state.loaded=true;
+      setStatus("Bookings aren’t available in this view. Open the page signed in to claude.ai to book a mat.");
+      render(); return;
+    }
+    if(user){
+      state.me = await user.id();
+      state.isOwner = await user.isOwner();
+      const w = await user.can("data.write");
+      if(w===false) state.canWrite=false;
+    }
+    const timer=setTimeout(()=>setStatus("Still reaching the booking list. Mat counts may be out of date."),10000);
+    db.collection("bookings").onSnapshot(snap=>{
+      const docs={};
+      snap.docs.forEach(d=>{const v=d.data(); if(v && Array.isArray(v.sessions)) docs[d.id]=v.sessions.filter(k=>typeof k==="string");});
+      state.docs=docs;
+      if(!snap.metadata.fromCache){
+        clearTimeout(timer);
+        if(!state.loaded){
+          state.loaded=true;
+          if(!state.me) setStatus("Sign in to claude.ai to book a mat. You can still browse the timetable.");
+          else if(!state.canWrite) setStatus("Your access to this page is view-only, so you can see the timetable but not book. Ask the studio for Contributor access.");
+          else setStatus("");
+        }
+      }
+      render();
+    }, err=>{
+      clearTimeout(timer); state.loaded=true;
+      setStatus("The booking list can’t be reached right now. Reload the page later to book.");
+      render();
+    });
+  })();
+})();
+</script>

