+.mine li:first-child{border-top:0;padding-top:0}
+.mine strong{display:block;font-weight:600;font-size:.95rem}
+.mine span{font-size:.82rem;color:var(--muted);font-variant-numeric:tabular-nums}
+.linkbtn{background:none;border:0;color:var(--accent);font-weight:600;font-size:.85rem;padding:4px}
